  "examples/2025-ai-sme-inclusive-up-to.covenant": "language covenant \"0.1\"\npackage g7.kananaskis_2025.ai_sme.inclusive_up_to version \"1.0.0\";\n\ncommitment AI_SME_ADOPTION {\n  title \"Inclusive arithmetic reading of up to four strong actions\";\n  subjects G7Members;\n  evaluation_window [2025-06-18, 2026-06-01];\n  evidence_policy open_world;\n  unknown_policy propagate;\n  action_identity review_required by underlying_instrument_id, program_family_id;\n\n  let strong_count: Int = count_distinct(actions where classification == strong distinct_by underlying_instrument_id);\n  let weak_count: Int = count_distinct(actions where classification == weak distinct_by underlying_instrument_id);\n  let counter_exists: Truth = exists(actions where classification == counter);\n\n  score {\n    result \"+1\" priority 10 when strong_count >= 5 id full;\n    result \"0\" priority 10 when (strong_count between {0, 4}) or\n      (weak_count between {3, 4}) id partial_inclusive_up_to;\n    result \"-1\" priority 10 when counter_exists or\n      (strong_count == 0 and weak_count <= 2) id none;\n    otherwise unresolved \"The source phrase remains operationally ambiguous.\";\n  }\n\n  assert exhaustive over strong_count in 0..8, weak_count in 0..8, counter_exists in {true, false};\n  assert non_overlapping over strong_count in 0..8, weak_count in 0..8, counter_exists in {true, false};\n}\n\nscenario zero_strong_low_weak_overlap for AI_SME_ADOPTION {\n  given strong_count = 0;\n  given weak_count = 0;\n  given counter_exists = false;\n  expect diagnostic COV-SCORE-OVERLAP;\n}\n",
